try {
const f = $input.first().json.files || [];
if (!f.length) throw new Error('Arquivo nexxusdoc_custos_n8n.json nao encontrado em Sua Area > Nexxus > NexxusDoc.');
return [{ json: { id: f[0].id } }];
} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Custos: escolher estado] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const MESES = ['JANEIRO', 'FEVEREIRO', 'MARCO', 'ABRIL', 'MAIO', 'JUNHO', 'JULHO', 'AGOSTO', 'SETEMBRO', 'OUTUBRO', 'NOVEMBRO', 'DEZEMBRO'];
const sem = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
const est = $('Custos: baixar estado').first().json || {};
const pastas = $input.all().flatMap(it => it.json.files || []).filter(p => MESES.includes(sem(p.name)));
if (!pastas.length) throw new Error('Pastas de mes nao encontradas em Layouts - MIRO de Deb. Post.');
const desde = new Date(new Date(est.ultima_execucao || '2026-11-24T00:00:00Z').getTime() - 10 * 60000).toISOString().slice(0, 19);
const q = '(' + pastas.map(p => "'" + p.id + "' in parents").join(' or ') + ") and modifiedTime > '" + desde + "' and trashed = false and mimeType != 'application/vnd.google-apps.folder'";
return [{json: {q, _agora: new Date().toISOString().slice(0, 19) + 'Z', _meses: Object.fromEntries(pastas.map(p => [p.id, p.name]))}}];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Custos: consulta] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const est = $('Custos: baixar estado').first().json || {};
const cons = $('Custos: consulta').first().json;
const ja = est.arquivos || {};
const vistos = new Set();
let fila = [];
for (const p of (est.pendentes || [])) { if (!vistos.has(p.drive_id)) { vistos.add(p.drive_id); fila.push({...p}); } }
const alterados = $input.all().flatMap(it => it.json.files || []).filter(f => /\.csv$/i.test(f.name || ''));
for (const f of alterados) {
  if (vistos.has(f.id)) continue;
  const atual = ja[String(f.name).toUpperCase()];
  if (atual && atual.drive_id === f.id && atual.mod_drive === f.modifiedTime) continue;
  vistos.add(f.id);
  fila.push({drive_id: f.id, nome: f.name, pasta: cons._meses[(f.parents || [])[0]] || '', mod_drive: f.modifiedTime, tentativas: 0});
}
fila.sort((a, b) => String(a.mod_drive).localeCompare(String(b.mod_drive)));
const agora = fila.slice(0, 120), resto = fila.slice(120);
const out = agora.length ? agora.map(f => ({json: {...f}})) : [{json: {dummy: true}}];
out[0].json._pendentes = resto.map(f => ({...f}));
out[0].json._alterados = alterados.length;
return out;

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Custos: fila] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {
// ===== Leitura dos layouts de MIRO de debito posterior (igual ao custos.py do NexxusDoc) =====
const RUB_GRUPO = {
  'PGTOFRETE': 'frete', 'PGTOBUNKER': 'frete', 'PGTOFOSSIL': 'frete', 'PGTOTXADD FRET': 'frete', 'PGTOECODELIV': 'frete',
  'PGTOCAPATAZIAS': 'porto', 'PGTOCEMERCANTE': 'porto', 'PGTOJUROSMMERC': 'porto', 'PGTODEMURRAGE': 'porto',
  'DEBITOII/1% Cof': 'impostos', 'DEBITOTX. SISC.': 'impostos', 'DEBITODUMPING': 'impostos', 'DEBITOMULTA': 'impostos',
  'PGTOARMAZ': 'armazenagem', 'PGTOARMAZDSA': 'armazenagem', 'PGTOFRETEROD': 'transporte', 'PGTOFRETRODCPL': 'transporte',
  'PGTOAJDESCARGA': 'transporte', 'PGTOTRAVAELET': 'transporte', 'PGTODESEMB': 'desembaraco', 'PGTOCOORDENA': 'desembaraco',
  'PGTOSERVADM': 'desembaraco', 'PGTOSERVLI': 'desembaraco', 'PGTOFLOWLS': 'desembaraco', 'PGTOSEGURO': 'seguro', 'PGTOADMSEG': 'seguro'
};
function rubricaGrupo(codigo) {
  const c = String(codigo || '').toUpperCase().replace(/^(PGTO|PREST(A[CÇ][AÃ]O)?|ANTECIPA[CÇ][AÃ]O|D[EÉ]BITO)\s*/, '');
  for (const [k, g] of Object.entries(RUB_GRUPO)) if (k.replace(/^(PGTO|DEBITO)/, '') === c) return g;
  if (/FRETE ?ROD|FRETROD|FRETENACIO|AJDESC|TRAVA|MOTO|TTMS/.test(c)) return 'transporte';
  if (c.includes('ARMAZ')) return 'armazenagem';
  if (/II|SISC|DUMPING|MULTA/.test(c) && !c.includes('SERV')) return 'impostos';
  if (/CAPATAZ|MERC|DEMURR|INSPE|MOVCARGA|TRANSPTER|FOTOGRAF/.test(c)) return 'porto';
  if (/FRETE|BUNKER|FOSSIL|BL|DELIV|CONSOL|COLLECT|CHC|DOC FEE|IOF/.test(c)) return 'frete';
  if (c.includes('SEGUR')) return 'seguro';
  if (/DESEMB|SERV|COORD|FLOWLS|SISTEMA|ADM|CARTA|DESP|JURO/.test(c)) return 'desembaraco';
  return 'outros';
}
// Mesmo arredondamento do round(v, 2) do Python (pelo valor binario exato; toFixed faz o mesmo)
const r2 = v => Number(Number(v).toFixed(2));
function numBR(v) {
  v = String(v || '').trim().replace(/^"|"$/g, '').replace(/ /g, '');
  if (!v) return 0;
  if (v.includes(',')) v = v.replace(/\./g, '').replace(',', '.');
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}
function dataBR(v) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})/.exec(String(v || '').trim().replace(/^"|"$/g, ''));
  return m ? `${m[3]}-${m[2]}-${m[1]}` : '';
}
function tipoDoNome(nome) {
  const m = /^[\s_]*MIRO[\s_]+DE[\s_]+(IMPOSTOS|DESPESAS|FRETE)/.exec(String(nome || '').toUpperCase());
  return m ? m[1].toLowerCase() : 'outro';
}
function lerLayout(txt, nome) {
  // Baixado como texto UTF-8: o raro espaco especial do cp1252 (\xa0 apos o BL) vira caractere invalido; sai aqui
  txt = String(txt || '').replace(/^﻿/, '').replace(/�/g, '');
  const linhas = txt.split(/\r\n|\r|\n/).filter(l => l.trim());
  if (linhas.length < 2) return null;
  const rub = {}, itens = {}, ordem = [];
  let ref = '', emp = '', data = '';
  for (const l of linhas.slice(1)) {
    const c = l.split(';').map(v => v.trim().replace(/^"+|"+$/g, '').trim());
    if (c.length < 24) continue;
    ref = ref || c[0]; emp = emp || c[5]; data = data || dataBR(c[3]);
    const cod = c[15] || '(sem texto)';
    if (!rub[cod]) rub[cod] = {fornecedor: c[6], cabecalho: c[13], atribuicao: c[14], nf: 0, _refs: [], venc: dataBR(c[10]), total: 0, itens: 0};
    const r = rub[cod];
    if (!r._refs.includes(c[0])) { r._refs.push(c[0]); r.nf += numBR(c[9]); }
    const v = numBR(c[22]);
    r.total += v; r.itens += 1;
    const k = c[18] + '/' + (c[19].replace(/^0+/, '') || c[19]);
    if (!itens[k]) { itens[k] = {po: c[18], item: c[19], qtd: numBR(c[23]), valores: {}}; ordem.push(k); }
    itens[k].valores[cod] = r2((itens[k].valores[cod] || 0) + v);
  }
  if (!Object.keys(rub).length) return null;
  for (const r of Object.values(rub)) { delete r._refs; r.total = r2(r.total); r.nf = r2(r.nf); }
  const nm = String(nome || '').toUpperCase();
  const wf = /WFADIM\d{8,9}/.exec(nm);
  const ver = /-(\d{1,2})(?:\s|\.CSV|$)/.exec(nm.replace(/\.CSV$/, '') + ' ');
  return {nome, tipo: tipoDoNome(nome), versao: ver ? Number(ver[1]) : 1, wfadim: wf ? wf[0] : '', ref, empresa: emp, data,
          rubricas: rub, itens: ordem.map(k => itens[k])};
}
function compacto(a) {
  const pos = {};
  for (const it of a.itens || []) {
    const p = pos[it.po] = pos[it.po] || {qtd: 0, itens: 0, g: {}};
    p.itens += 1; p.qtd += it.qtd || 0;
    for (const [cod, v] of Object.entries(it.valores)) { const g = rubricaGrupo(cod); p.g[g] = r2((p.g[g] || 0) + v); }
  }
  const out = {};
  for (const [k, v] of Object.entries(a)) if (k !== 'itens') out[k] = v;
  out.pos = pos; out.n_itens = (a.itens || []).length;
  return out;
}

// ===== Le os CSVs baixados e grava o estado (so o n8n escreve este arquivo) =====
const estado = JSON.parse(JSON.stringify($('Custos: baixar estado').first().json || {}));
const cons = $('Custos: consulta').first().json;
const fila = $('Custos: fila').all();
const seguro = n => { try { return $(n).all(); } catch (e) { return []; } };
const baixados = seguro('Custos: baixar layouts');
estado.arquivos = estado.arquivos || {};
const pend = (((fila[0] || {}).json || {})._pendentes || []).map(p => ({...p}));
let lidos = 0, erros = 0;
const ultimosErros = [];
fila.forEach((it, i) => {
  const meta = it.json;
  if (meta.dummy || !meta.drive_id) return;
  const r = (baixados[i] || {}).json || {};
  const txt = typeof r.data === 'string' ? r.data : '';
  const a = txt && !r.error ? lerLayout(txt, meta.nome) : null;
  if (!a) {
    erros++;
    ultimosErros.push({nome: meta.nome, erro: r.error ? 'não foi possível baixar' : 'layout vazio ou fora do formato'});
    if ((meta.tentativas || 0) < 2) { const p = {...meta, tentativas: (meta.tentativas || 0) + 1}; delete p._pendentes; delete p._alterados; pend.push(p); }
    return;
  }
  const c = compacto(a);
  c.mod = String(meta.mod_drive || '').slice(0, 19);
  c.mod_drive = meta.mod_drive; c.drive_id = meta.drive_id; c.pasta = meta.pasta;
  c.caminho = (meta.pasta ? meta.pasta + '\\' : '') + meta.nome;
  c.lido_em = cons._agora;
  estado.arquivos[String(meta.nome).toUpperCase()] = c;
  lidos++;
});
estado.versao = 1;
estado.ultima_execucao = cons._agora;
estado.pendentes = pend;
estado.ultima_rodada = {em: cons._agora, alterados: ((fila[0] || {}).json || {})._alterados || 0, lidos, erros,
  pendentes: pend.length, erros_exemplo: ultimosErros.slice(0, 5)};
return [{json: {id: $('Custos: escolher estado').first().json.id, conteudo: JSON.stringify(estado)}}];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[Custos: ler e montar estado] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}
